10	/**
11	 * Same path the scraper and facebook:auth script use.
12	 * Kept here (not imported into the scraper) so connection management
13	 * can evolve without touching scrape behavior.
14	 */
15	const FACEBOOK_STORAGE_STATE_PATH = path.join(
16	  process.cwd(),
17	  'storage',
18	  'facebook-state.json',
19	)
20	
21	const AUTH_COMMAND = 'npm run facebook:auth'
22	
23	function baseConnection(
24	  partial: Pick<ProviderConnection, 'status' | 'lastConnectedAt' | 'message'>,
25	): ProviderConnection {
26	  return {
27	    providerId: 'facebook',
28	    displayName: 'Facebook Marketplace',
29	    description:
30	      'Optional authenticated Facebook session. Scout searches Marketplace anonymously by default.',
31	    ...partial,
32	  }
33	}
34	
35	function readSessionFileMeta(): {
36	  exists: boolean
37	  lastConnectedAt: string | null
38	  parseError: boolean
39	} {
40	  if (!fs.existsSync(FACEBOOK_STORAGE_STATE_PATH)) {
41	    return { exists: false, lastConnectedAt: null, parseError: false }
42	  }
43	
44	  let lastConnectedAt: string | null = null
45	  try {
46	    const stats = fs.statSync(FACEBOOK_STORAGE_STATE_PATH)
47	    lastConnectedAt = stats.mtime.toISOString()
48	  } catch {
49	    lastConnectedAt = null
50	  }
51	
52	  try {
53	    const raw = fs.readFileSync(FACEBOOK_STORAGE_STATE_PATH, 'utf8')
54	    const parsed = JSON.parse(raw) as { cookies?: unknown }
55	    if (!parsed || !Array.isArray(parsed.cookies)) {
56	      return { exists: true, lastConnectedAt, parseError: true }
57	    }
58	    return { exists: true, lastConnectedAt, parseError: false }
59	  } catch {
60	    return { exists: true, lastConnectedAt, parseError: true }
61	  }
62	}
63	
64	function resolveConnection(): ProviderConnection {
65	  const meta = readSessionFileMeta()
66	
67	  if (!meta.exists) {
68	    return baseConnection({
69	      status: 'not_connected',
70	      lastConnectedAt: null,
71	      message:
72	        'No authenticated session saved. Scout still searches Marketplace anonymously.',
73	    })
74	  }
75	
76	  if (meta.parseError) {
77	    return baseConnection({
78	      status: 'connection_error',
79	      lastConnectedAt: meta.lastConnectedAt,
80	      message:
81	        'A Facebook session file was found but could not be read. Reconnect to fix this.',
82	    })
83	  }
84	
85	  // session_expired is reserved for later detection (e.g. scraper hits login).
86	  // A valid session file means an optional authenticated fallback is available.
87	  return baseConnection({
88	    status: 'connected',
89	    lastConnectedAt: meta.lastConnectedAt,
90	    message:
91	      'Optional authenticated session is saved. Scout searches Marketplace anonymously by default.',
92	  })
93	}
94	
95	function connectViaExistingAuthScript(): ConnectProviderResult {
96	  const connection = resolveConnection()
97	
98	  return {
99	    providerId: 'facebook',
100	    connection,
101	    action: {
102	      mode: 'external_script',
103	      command: AUTH_COMMAND,
104	      message:
105	        connection.status === 'connected'
106	          ? 'An authenticated session is already saved. To refresh it, run the optional auth utility in tracker-api, then refresh status here.'
107	          : 'Optional: complete Facebook login with the auth utility in tracker-api (`npm run facebook:auth`), then refresh status. Marketplace searches work anonymously without this.',
108	    },
109	  }
110	}
111	
112	export const facebookConnectionService: ProviderConnectionService = {
113	  providerId: 'facebook',
114	
115	  async getConnection() {
116	    return resolveConnection()
117	  },
118	
119	  async connect() {
120	    return connectViaExistingAuthScript()
121	  },
122	
123	  async reconnect() {
124	    return connectViaExistingAuthScript()
125	  },
126	
127	  async disconnect() {
128	    return {
129	      providerId: 'facebook',
130	      implemented: false,
131	      message:
132	        'Disconnect is not implemented yet. Remove storage/facebook-state.json manually if you need to clear the session.',
133	      connection: resolveConnection(),
134	    }
135	  },
136	}
